const form=document.querySelector('#result-form'),status=document.querySelector('#save-status'),sportSelect=document.querySelector('#sport-select');let data,recordId=crypto.randomUUID(),revision=0,busy=false;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,options){const response=await fetch(path,{cache:'no-store',...options,signal:AbortSignal.timeout(15000)});let value;try{value=await response.json()}catch{throw Error('Không tải được dữ liệu. Vui lòng thử lại.')}if(!response.ok)throw Error(value.error||'Không thể xử lý yêu cầu.');return value}
async function reload(){try{data=await api('/api/scoreboard');renderList();document.querySelector('#list-status').textContent=''}catch(e){document.querySelector('#list-status').textContent=e.message;throw e}}
function renderList(){const rows=data.results;document.querySelector('#admin-results').innerHTML=rows.length?rows.map(r=>{const sport=data.sports.find(s=>s.id===r.sport_id);return `<article class="admin-record"><div class="record-details"><h3>${esc(r.event)}</h3><dl><dt>Môn thi đấu</dt><dd>${esc(sport?.name)} – ${esc(sport?.discipline)}</dd><dt>Trận/Phần thi</dt><dd>${esc(r.event)}</dd><dt>Đội/VĐV</dt><dd>${esc(r.participants)}</dd><dt>Kết quả</dt><dd>${esc(r.score)}</dd>${['gold','silver','bronze'].map(m=>`<dt>${{gold:'HCV',silver:'HCB',bronze:'HCĐ'}[m]}</dt><dd>${r[m]?esc(data.alliances.find(a=>a.id===r[m])?.name):'Chưa trao'}</dd>`).join('')}<dt>Thời gian cập nhật</dt><dd><time datetime="${esc(r.updated_at)}">${esc(new Intl.DateTimeFormat('vi-VN',{dateStyle:'short',timeStyle:'medium',timeZone:'Asia/Ho_Chi_Minh'}).format(new Date(r.updated_at)))}</time> (giờ Việt Nam)</dd></dl></div><div class="record-actions"><button type="button" class="button" data-edit="${esc(r.id)}">Sửa kết quả</button><button type="button" class="button delete-result" data-delete="${esc(r.id)}">Xóa kết quả</button></div></article>`}).join(''):'<p>Chưa có kết quả đã nhập.</p>';document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{if(busy)return;const r=data.results.find(r=>r.id===b.dataset.edit);recordId=r.id;revision=r.revision;for(const key of ['sport_id','event','participants','score','gold','silver','bronze'])form.elements[key].value=r[key]??'';document.querySelector('#form-title').textContent='Sửa kết quả';status.textContent='Đang sửa kết quả đã lưu. Huy chương cũ sẽ được thay thế bằng lựa chọn mới.';form.scrollIntoView({behavior:'smooth',block:'start'});form.elements.event.focus()});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(busy)return;pendingDelete={...data.results.find(r=>r.id===b.dataset.delete)};deleteTrigger=b;document.querySelector('#delete-description').textContent='Xóa kết quả “'+pendingDelete.event+'”? Huy chương của kết quả này sẽ được loại khỏi bảng tổng sắp. Thao tác không thể hoàn tác.';document.querySelector('#delete-status').textContent='';deleteDialog.showModal()})}
let pendingDelete=null,deleteTrigger=null;const deleteDialog=document.querySelector('#delete-dialog');document.querySelector('#cancel-delete').onclick=()=>deleteDialog.close();deleteDialog.addEventListener('cancel',e=>{if(busy)e.preventDefault()});deleteDialog.addEventListener('close',()=>{pendingDelete=null;if(deleteTrigger?.isConnected)deleteTrigger.focus();else document.querySelector('#reload-button').focus()});document.querySelector('#confirm-delete').onclick=async()=>{if(busy||!pendingDelete)return;busy=true;const target=pendingDelete;const controls=[...document.querySelectorAll('#admin-workspace button,#admin-workspace input,#admin-workspace textarea,#admin-workspace select,#delete-dialog button')];controls.forEach(c=>c.disabled=true);const message=document.querySelector('#delete-status');message.textContent='Đang xóa kết quả…';try{await api('/api/admin/results',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:target.id,revision:target.revision})});if(recordId===target.id)fresh();deleteDialog.close();await reload();document.querySelector('#list-status').textContent='Đã xóa kết quả. Huy chương đã được tính lại; website người xem tự cập nhật trong khoảng 5 giây.'}catch(e){const text=e.name==='TimeoutError'?'Chưa xác nhận được thao tác xóa. Hãy thử lại hoặc tải lại danh sách.':e.message;if(deleteDialog.open)message.textContent=text;else document.querySelector('#list-status').textContent='Thao tác xóa đã gửi. '+text}finally{busy=false;controls.forEach(c=>c.disabled=false)}};

function fresh(){recordId=crypto.randomUUID();revision=0;for(const k of ['event','participants','score','gold','silver','bronze'])form.elements[k].value='';document.querySelector('#form-title').textContent='Thêm kết quả';status.textContent=''}
sportSelect.onchange=()=>{fresh();renderList()};document.querySelector('#new-button').onclick=fresh;document.querySelector('#reload-button').onclick=()=>reload().catch(()=>{});
form.onsubmit=async e=>{e.preventDefault();if(busy||!form.reportValidity())return;const payload={id:recordId,revision,sport_id:Number(sportSelect.value)};for(const k of ['event','participants','score'])payload[k]=form.elements[k].value;for(const k of ['gold','silver','bronze'])payload[k]=form.elements[k].value?Number(form.elements[k].value):null;busy=true;const controls=[...form.querySelectorAll('input,select,textarea,button')];controls.forEach(c=>c.disabled=true);status.textContent='Đang cập nhật kết quả…';try{const saved=await api('/api/admin/results',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});revision=saved.revision;document.querySelector('#form-title').textContent='Sửa kết quả';status.textContent='Đã cập nhật. Người xem sẽ thấy kết quả và bảng huy chương trong khoảng 5 giây.';await reload()}catch(e){status.textContent=e.name==='TimeoutError'?'Chưa xác nhận được kết quả lưu. Giữ nguyên nội dung và bấm cập nhật lại để kiểm tra.':e.message}finally{busy=false;controls.forEach(c=>c.disabled=false)}};
(async()=>{try{await api('/api/admin/session');await reload();sportSelect.innerHTML=data.sports.map(s=>`<option value="${s.id}">${esc(s.name)} – ${esc(s.discipline)}</option>`).join('');for(const medal of ['gold','silver','bronze'])form.elements[medal].innerHTML='<option value="">Chưa trao</option>'+data.alliances.map(a=>`<option value="${a.id}">LIÊN MINH ${esc(a.name)}</option>`).join('');document.querySelector('#admin-status').textContent='Chỉ tài khoản quản trị được cập nhật kết quả.';document.querySelector('#admin-workspace').hidden=false;renderList()}catch(e){document.querySelector('#admin-status').textContent=e.message}})();
